        obj = json.loads(line.strip())
        t = obj.get('type', '?')
        if t == 'user' and 'message' in obj:
            msg = obj['message']
            content = msg.get('content', '')
            if isinstance(content, list):
                for item in content:
                    if isinstance(item, dict):
                        if item.get('type') == 'tool_result':
                            r = str(item.get('content', ''))[:600]
